<?php include 'db.php'; require_role('Doctor'); $did=current_entity_id($conn,'Doctor'); $page_title='Doctor Dashboard'; include 'header.php'; ?>
<h2>Doctor Dashboard</h2><h3>Assigned Appointments</h3><table><tr><th>ID</th><th>Patient</th><th>Test</th><th>Room</th><th>Date</th><th>Status</th><th>Action</th></tr><?php $res=$conn->query("SELECT A.*, CONCAT(P.First_Name,' ',P.Last_Name) Patient_Name, CONCAT(D.First_Name,' ',D.Last_Name) Doctor_Name, CONCAT(N.First_Name,' ',N.Last_Name) Nurse_Name, RT.Test_Name, R.Room_Name, Pay.Payment_Status
FROM APPOINTMENT A JOIN PATIENT P ON A.Patient_ID=P.Patient_ID JOIN DOCTOR D ON A.Doctor_ID=D.Doctor_ID LEFT JOIN NURSE N ON A.Nurse_ID=N.Nurse_ID JOIN RADIOLOGY_TEST RT ON A.Test_ID=RT.Test_ID JOIN ROOM R ON A.Room_ID=R.Room_ID LEFT JOIN PAYMENT Pay ON A.Appointment_ID=Pay.Appointment_ID WHERE A.Doctor_ID=$did ORDER BY A.Appointment_Date DESC"); while($r=$res->fetch_assoc()): ?><tr><td><?=esc($r['Appointment_ID'])?></td><td><?=esc($r['Patient_Name'])?></td><td><?=esc($r['Test_Name'])?></td><td><?=esc($r['Room_Name'])?></td><td><?=esc($r['Appointment_Date'])?></td><td><?=esc($r['Status'])?></td><td><a class="btn" href="add_report.php?id=<?=$r['Appointment_ID']?>">Write Report</a></td></tr><?php endwhile; ?></table><?php include 'footer.php'; ?>